 public sealed class ProgressPacket {public int Value;public string Message;}
 public sealed class ProgressMailbox {
  readonly object gate=new object();ProgressPacket latest;public long Received,Delivered;
  public void Publish(int value,string message){lock(gate){Received++;latest=new ProgressPacket{Value=value,Message=message};}}
  public ProgressPacket Take(){lock(gate){var value=latest;latest=null;if(value!=null)Delivered++;return value;}}
  public void Clear(){lock(gate)latest=null;}
 }
 public partial class MainForm {
  readonly ProgressMailbox progressMailbox=new ProgressMailbox();readonly Timer progressPump=new Timer{Interval=100};System.Threading.CancellationTokenSource importCancellation;bool targetConfirmed;readonly Dictionary<Row,string> searchIndex=new Dictionary<Row,string>();
  void Report(int value,string message){progressMailbox.Publish(value,message);}
  void DrainProgress(){var packet=progressMailbox.Take();if(packet==null||IsDisposed)return;progress.Value=Math.Max(0,Math.Min(100,packet.Value));status.Text=packet.Message;if(packet.Value==100||DateTime.UtcNow-lastProgressLog>TimeSpan.FromMilliseconds(350)){lastProgressLog=DateTime.UtcNow;Append(packet.Message);}}
  void BuildResponsive(){Font=new Font("Microsoft JhengHei UI",11);progressPump.Tick+=delegate{if(busy)DrainProgress();};progressPump.Start();FormClosed+=delegate{progressPump.Dispose();};
   grid.Columns[2].DefaultCellStyle.Padding=new Padding(10,8,28,8);((DataGridViewComboBoxColumn)grid.Columns[2]).DisplayStyle=DataGridViewComboBoxDisplayStyle.Nothing;grid.EditMode=DataGridViewEditMode.EditProgrammatically;
   grid.CellPainting+=delegate(object sender,DataGridViewCellPaintingEventArgs e){if(e.RowIndex<0||e.ColumnIndex!=2)return;e.Paint(e.ClipBounds,DataGridViewPaintParts.All);if(rows.Count>e.RowIndex&&rows[e.RowIndex].Package!=null){var box=new Rectangle(e.CellBounds.Right-26,e.CellBounds.Y+e.CellBounds.Height/2-8,18,16);TextRenderer.DrawText(e.Graphics,"⌄",Font,box,Themes.Current.Accent,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}e.Handled=true;};
   grid.KeyDown+=delegate(object sender,KeyEventArgs e){if((e.KeyCode==Keys.F4||e.Alt&&e.KeyCode==Keys.Down)&&grid.CurrentRow!=null){ShowVersionPicker(grid.CurrentRow.Index);e.SuppressKeyPress=true;}};
   WrapInputs();CompactDetailActions();AddSectionSurfaces();AddScrollSkins();navigation.SizeChanged+=delegate{FitNavigation();};Theme(this);UpdateNavigation();
  }
  void WrapInputs(){foreach(var text in FindControls(this).OfType<TextBox>().Where(t=>!t.Multiline&&!t.ReadOnly).ToArray()){var parent=text.Parent;if(parent==null||parent is InputFrame)continue;var table=parent as TableLayoutPanel;var position=table==null?new TableLayoutPanelCellPosition():table.GetPositionFromControl(text);int order=parent.Controls.GetChildIndex(text);var frame=new InputFrame{Dock=text.Dock,Width=text==search?260:text.Width,Height=38,Margin=table==null?text.Margin:new Padding(4,3,4,3)};parent.Controls.Remove(text);text.Dock=DockStyle.Fill;text.Margin=Padding.Empty;text.AutoSize=false;text.Enter+=delegate{frame.Invalidate();};text.Leave+=delegate{frame.Invalidate();};frame.Controls.Add(text);if(table!=null)table.Controls.Add(frame,position.Column,position.Row);else{parent.Controls.Add(frame);parent.Controls.SetChildIndex(frame,order);}}}
  void CompactDetailActions(){var parent=(TableLayoutPanel)installCurrent.Parent.Parent;var old=installCurrent.Parent;var tools=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2,Margin=Padding.Empty};tools.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));tools.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));tools.RowStyles.Add(new RowStyle(SizeType.Percent,50));tools.RowStyles.Add(new RowStyle(SizeType.Percent,50));var buttons=new[]{installCurrent,openCurrent,copyCurrent,historyCurrent};string[] keys={"DetailInstall","DetailSource","DetailCopy","DetailVersions"};for(int i=0;i<buttons.Length;i++){old.Controls.Remove(buttons[i]);buttons[i].AutoSize=false;buttons[i].Dock=DockStyle.Fill;buttons[i].Text=L.Get(keys[i]);textKeys[buttons[i]]=keys[i];tools.Controls.Add(buttons[i],i%2,i/2);}parent.Controls.Remove(old);old.Dispose();parent.RowStyles[1].Height=100;parent.Controls.Add(tools,0,1);}
  string SearchText(Row row){string value;if(searchIndex.TryGetValue(row,out value))return value;List<string> categories;settings.modCategories.TryGetValue(RowId(row),out categories);value=RawName(row)+" "+RowId(row)+" "+(categories==null?"":string.Join(" ",categories))+" "+(row.Options==null?row.Installed.name:string.Join(" ",row.Options.Select(o=>ModNames.Search(o.Package)+" "+PackageVersions.Display(o.Package)+" "+L.Text(o.Package.Origin))));searchIndex[row]=value;return value;}
  void FitNavigation(){if(navigation==null)return;foreach(var button in navButtons.Concat(new[]{navToggle})){if(button!=null)button.Width=Math.Max(26,navigation.ClientSize.Width-navigation.Padding.Horizontal-button.Margin.Horizontal);}}
  void ShowVersionPicker(int index){if(busy||index<0||index>=rows.Count||rows[index].Package==null)return;var row=rows[index];var menu=new ContextMenuStrip{Renderer=new ThemeMenuRenderer(),BackColor=Themes.Current.Surface,ForeColor=Themes.Current.Text,ShowImageMargin=false};foreach(var option in row.Options){var chosen=option;var item=new ToolStripMenuItem(option.Label){Checked=Data.Same(option.Key,row.Package.Folder),ToolTipText=option.Key};item.Click+=delegate{grid.Rows[index].Cells[2].Value=chosen.Key;};menu.Items.Add(item);}menu.Closed+=delegate{MenuLifetime.Release(this,menu);};var cell=grid.GetCellDisplayRectangle(2,index,true);menu.Show(grid,new Point(cell.Left,cell.Bottom));}
  void AddSectionSurfaces(){
   var library=(TableLayoutPanel)detailSplit.Parent;WrapSection(library,filters,null);library.RowStyles[0].Height=136;WrapSection(detailSplit.Panel1,grid,L.Get("Text024"));WrapSection((Control)detail.Parent,detail,L.Get("ModDetails"));WrapSection(dashboardShell,navigation,L.Get("Navigation"));
   foreach(var page in new[]{tabs.TabPages[1],tabs.TabPages[2],tabs.TabPages[3],problemPage,overviewPage}){if(page.Controls.Count==0)continue;var content=page.Controls[0];WrapSection(page,content,page.Text);}
  }
  void AddScrollSkins(){foreach(var control in FindControls(this).ToArray()){if(control.Parent is ScrollSurface||control.Parent!=null&&control.Parent.Parent is ScrollSurface)continue;if(!(control is DataGridView)&&!(control is ListBox)&&!(control is FlowLayoutPanel&&((FlowLayoutPanel)control).AutoScroll)&&!(control is Panel&&!(control is SectionPanel)&&((Panel)control).AutoScroll))continue;var parent=control.Parent;if(parent==null)continue;var table=parent as TableLayoutPanel;var position=table==null?new TableLayoutPanelCellPosition():table.GetPositionFromControl(control);int order=parent.Controls.GetChildIndex(control);var dock=control.Dock;var margin=control.Margin;parent.Controls.Remove(control);var skin=new ScrollSurface(control){Dock=dock,Margin=margin};if(table!=null)table.Controls.Add(skin,position.Column,position.Row);else{parent.Controls.Add(skin);parent.Controls.SetChildIndex(skin,order);}}}
  void WrapSection(Control parent,Control content,string title){var table=parent as TableLayoutPanel;var position=table==null?new TableLayoutPanelCellPosition():table.GetPositionFromControl(content);var host=new SectionPanel{Dock=DockStyle.Fill,Title=title,TitleKey=L.Key(title),Margin=new Padding(4),Padding=title==null?new Padding(12,10,12,8):new Padding(12,42,12,12)};if(content==navigation){host.Title=null;host.Padding=new Padding(4);navigation.AutoScroll=false;}parent.Controls.Remove(content);content.Dock=DockStyle.Fill;if(content is DataGridView||content is TextBox&&((TextBox)content).Multiline||content is ListBox)host.Controls.Add(new ScrollSurface(content){Dock=DockStyle.Fill});else host.Controls.Add(content);if(table==null)parent.Controls.Add(host);else table.Controls.Add(host,position.Column,position.Row);}
  void UpdateGuide(){if(overviewPage==null)return;overviewPage.Text=L.Get("Guide");navKeys[0]="Guide";foreach(var section in FindControls(this).OfType<SectionPanel>())if(section.TitleKey!=null)section.Title=L.Get(section.TitleKey);}
  async Task MergeCatalog(IEnumerable<Package> additions,IEnumerable<string> removed){var removedRoots=(removed??new string[0]).ToArray();var selected=Selected().Select(RowId).ToHashSetCompat();var installed=rows.Where(r=>r.Installed!=null).Select(r=>r.Installed).ToList();var all=rows.Where(r=>r.Options!=null).SelectMany(r=>r.Options).Select(o=>o.Package).Where(p=>!removedRoots.Any(root=>PackageVersions.Under(p.Folder,root))).Concat(additions??new Package[0]).ToList();rows.Clear();foreach(var group in all.GroupBy(p=>p.Manifest.id)){var options=PackageVersions.Options(group);string saved;settings.versionChoices.TryGetValue(group.Key,out saved);var p=PackageVersions.Choose(options,saved).Package;rows.Add(new Row{Package=p,Options=options,Installed=installed.FirstOrDefault(i=>i.id==group.Key),ServerIssue=serverMode?p.ServerIssue:null});}foreach(var old in installed.Where(i=>!rows.Any(r=>RowId(r)==i.id)))rows.Add(new Row{Installed=old});populating=true;grid.Rows.Clear();populating=false;RefreshTargets();DetectConflictsWithoutGrid(installed);SortRows();populating=true;foreach(DataGridViewRow line in grid.Rows)line.Cells[0].Value=line.Visible&&selected.Contains(RowId(rows[line.Index]));populating=false;RefreshVersions();UpdateSelection();RefreshProblems();await Task.FromResult(0);}
 }
 static class CollectionCompatibility {public static HashSet<string> ToHashSetCompat(this IEnumerable<string> values){return new HashSet<string>(values,StringComparer.OrdinalIgnoreCase);}}
